#include "attitudeSafetyQualifier_behavior.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void attitudeSafetyQualifier_behavior_initialize(void);
void attitudeSafetyQualifier_behavior_notify(microkit_channel channel);
void attitudeSafetyQualifier_behavior_timeTriggered(void);

volatile sb_queue_FlightStack_QualifiedAttitude_1_t *qualifiedAttitude_queue_1;
volatile sb_queue_FlightStack_AircraftAttitude_1_t *aircraftAttitude_queue_1;
sb_queue_FlightStack_AircraftAttitude_1_Recv_t aircraftAttitude_recv_queue;

#define PORT_FROM_MON 58

bool put_qualifiedAttitude(const FlightStack_QualifiedAttitude *data) {
  sb_queue_FlightStack_QualifiedAttitude_1_enqueue((sb_queue_FlightStack_QualifiedAttitude_1_t *) qualifiedAttitude_queue_1, (FlightStack_QualifiedAttitude *) data);

  return true;
}

FlightStack_AircraftAttitude last_aircraftAttitude_payload;

bool get_aircraftAttitude(FlightStack_AircraftAttitude *data) {
  sb_event_counter_t numDropped;
  FlightStack_AircraftAttitude fresh_data;
  bool isFresh = sb_queue_FlightStack_AircraftAttitude_1_dequeue((sb_queue_FlightStack_AircraftAttitude_1_Recv_t *) &aircraftAttitude_recv_queue, &numDropped, &fresh_data);
  if (isFresh) {
    last_aircraftAttitude_payload = fresh_data;
  }
  *data = last_aircraftAttitude_payload;
  return isFresh;
}

void init(void) {
  sb_queue_FlightStack_QualifiedAttitude_1_init((sb_queue_FlightStack_QualifiedAttitude_1_t *) qualifiedAttitude_queue_1);

  sb_queue_FlightStack_AircraftAttitude_1_Recv_init(&aircraftAttitude_recv_queue, (sb_queue_FlightStack_AircraftAttitude_1_t *) aircraftAttitude_queue_1);

  attitudeSafetyQualifier_behavior_initialize();
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      attitudeSafetyQualifier_behavior_timeTriggered();
      break;
    default:
      attitudeSafetyQualifier_behavior_notify(channel);
  }
}
